# patch_20261011_plain_to_html_unify.ps1
# One plain-text -> HTML conversion for all outbound mail (src/lib/email/plain-to-html.ts):
# blank line = paragraph, lines inside a paragraph joined with <br> (tight lists),
# inline 12px paragraph spacing, bare URLs become links. Replaces the 4 copies in
# send-outbound, communications, sequence-sender, sequence-processor. Also drops the
# two <br> before the signature rule. Writes nothing unless every file still matches
# the reviewed original (LF-normalized SHA-256). Idempotent. ASCII output only.
$Repo = "C:\dev\mbg-project"
function Sha([string]$t) { $b = [System.Text.Encoding]::UTF8.GetBytes($t); $h = [System.Security.Cryptography.SHA256]::Create().ComputeHash($b); ($h | ForEach-Object { $_.ToString("x2") }) -join "" }
$items = @(
  @{ Path = "src\lib\email\send-outbound.ts"; Old = "b07bfbc1adc18cae2559b2243e3436e54327c19ba8a9dfd8d14f4ab9a324a6ad"; New = "23172bdec83267d998937d347e1974aaebf13dde281bf9d0baacd2ccee3ef2f2"; B64 = "" },
  @{ Path = "src\lib\actions\communications.ts"; Old = "85dd8f46b0562f485e234de5fdcd5d5f61047fa3041399b32876e7f980c4289b"; New = "a1b7ec97ea84b7e0de9fcf091bdb262f9def06aef9f8ac52bb1877bb93dd8214"; B64 = "" },
  @{ Path = "src\lib\actions\sequence-sender.ts"; Old = "3710e527b8bfc179c5f8cb848bae67707714e63ffee1b3f81a4e5c8f4f17d843"; New = "3da5e2d021ddf941003d0d20afa03f448f96c71a4f4c10d969fffdea6b5a6a19"; B64 = "" },
  @{ Path = "src\lib\utils\sequence-processor.ts"; Old = "527758a7f5fcad318729f117098687d1ad51474db43ced63980636f403e73d64"; New = "fa4ba2117fa94194cc52c90f6c862fa8fe18dfa17b0b503a40764c55ddb4f0ff"; B64 = "" },
  @{ Path = "src\lib\email\plain-to-html.ts"; Old = "ABSENT"; New = "1464bfdbf7c70815b296f00bfdf581b99688356425a3b6f5d60e76c726b45563"; B64 = "" }
)
foreach ($it in $items) {
  $p = Join-Path $Repo $it.Path
  if (-not (Test-Path -LiteralPath $p)) { if ($it.Old -eq "ABSENT") { continue }; Write-Output ("ERROR missing " + $it.Path); return }
  $cur = Sha ([System.IO.File]::ReadAllText($p).Replace("`r`n", "`n"))
  if ($cur -ne $it.Old -and $cur -ne $it.New) { Write-Output ("ERROR changed since review, not patched: " + $it.Path); return }
}
foreach ($it in $items) {
  $p = Join-Path $Repo $it.Path
  if (Test-Path -LiteralPath $p) {
    $cur = Sha ([System.IO.File]::ReadAllText($p).Replace("`r`n", "`n"))
    if ($cur -eq $it.New) { Write-Output ("SKIP  already patched " + $it.Path); continue }
  }
  [System.IO.File]::WriteAllBytes($p, [System.Convert]::FromBase64String($it.B64))
  Write-Output ("PATCHED " + $it.Path)
}
